// This code has been fully generated by an AI.

// Package insight turns health values and training load into statements a
// user can act on: personal normal ranges, the readiness of the day, a
// training recommendation and an assessment of the intensity distribution.
//
// All rules are transparent and parameterized by Settings; the defaults
// were calibrated against Garmin's training readiness over 4.5 years of
// own data (docs/konzept-einordnung.md §12). Nothing here is a diagnosis.
package insight

import (
	"math"
	"sort"
	"time"
)

// Metric keys (columns of daily_health).
const (
	RestingHR = "resting_hr"
	HRV       = "hrv_night_avg"
	HRVLow    = "hrv_baseline_low"
	HRVHigh   = "hrv_baseline_high"
	Sleep     = "sleep_s"
	SleepScr  = "sleep_score"
	BodyHigh  = "body_battery_high"
	Stress    = "stress_avg"
)

// Columns lists the daily_health columns the package reads.
var Columns = []string{RestingHR, HRV, HRVLow, HRVHigh, Sleep, SleepScr, BodyHigh, Stress}

// Series holds daily values per metric: metric → local date (UTC midnight) → value.
type Series map[string]map[time.Time]float64

// Value returns the value of a metric on a day.
func (s Series) Value(metric string, day time.Time) (float64, bool) {
	v, ok := s[metric][day]
	return v, ok
}

// floors are the smallest spread per metric, so very stable values do not
// turn tiny changes into large deviations.
var floors = map[string]float64{RestingHR: 1, HRV: 2, Sleep: 900, SleepScr: 3, BodyHigh: 3, Stress: 2}

// higherIsBetter gives the favourable direction of a metric.
var higherIsBetter = map[string]bool{RestingHR: false, HRV: true, Sleep: true, SleepScr: true, BodyHigh: true, Stress: false}

// Normal is a personal normal range: median ± spread of the window before a day.
type Normal struct {
	Median, Spread float64
	N              int
}

// Low and High bound the normal range.
func (n Normal) Low() float64  { return n.Median - n.Spread }
func (n Normal) High() float64 { return n.Median + n.Spread }

// DailyTotals are metrics summed or averaged over a whole day; for today
// they are incomplete until the day is over.
var DailyTotals = map[string]bool{BodyHigh: true, Stress: true, "steps": true, "body_battery_low": true,
	"intensity_moderate_min": true, "intensity_vigorous_min": true, "spo2_avg": true, "respiration_avg": true}

// bounds clamps ranges of metrics with a fixed scale.
var bounds = map[string][2]float64{BodyHigh: {0, 100}, Stress: {0, 100}, SleepScr: {0, 100}}

// Range returns the normal range clamped to the scale of metric.
func (n Normal) Range(metric string) (lo, hi float64) {
	lo, hi = n.Low(), n.High()
	if b, ok := bounds[metric]; ok {
		lo, hi = max(lo, b[0]), min(hi, b[1])
	}
	return lo, hi
}

// NormalFor computes the normal range of metric from the window days before
// day (day itself excluded). The spread is the MAD scaled to a standard
// deviation (× 1.4826) with a per-metric minimum. ok is false with fewer
// than minDays values.
func NormalFor(s Series, metric string, day time.Time, window, minDays int) (Normal, bool) {
	var xs []float64
	for i := 1; i <= window; i++ {
		if v, ok := s.Value(metric, day.AddDate(0, 0, -i)); ok {
			xs = append(xs, v)
		}
	}
	if len(xs) < minDays {
		return Normal{}, false
	}
	m := median(xs)
	dev := make([]float64, len(xs))
	for i, x := range xs {
		dev[i] = math.Abs(x - m)
	}
	spread := math.Max(median(dev)*1.4826, floors[metric])
	return Normal{Median: m, Spread: spread, N: len(xs)}, true
}

func median(xs []float64) float64 {
	s := append([]float64(nil), xs...)
	sort.Float64s(s)
	n := len(s)
	if n%2 == 1 {
		return s[n/2]
	}
	return (s[n/2-1] + s[n/2]) / 2
}

// Deviation is a value compared with its normal range. Z is positive when
// the value is favourable.
type Deviation struct {
	Metric string
	Value  float64
	Normal Normal
	Z      float64
}

// Band classifies |Z|: 0 within the normal range, 1 slightly, 2 clearly
// outside.
func (d Deviation) Band() int {
	switch a := math.Abs(d.Z); {
	case a < 1:
		return 0
	case a < 2:
		return 1
	}
	return 2
}

// Deviate compares value with the normal range in the favourable direction.
func Deviate(metric string, value float64, n Normal) Deviation {
	z := (value - n.Median) / n.Spread
	if !higherIsBetter[metric] {
		z = -z
	}
	return Deviation{Metric: metric, Value: value, Normal: n, Z: z}
}

// DeviationOn compares the value of metric on day with its normal range.
// The resting heart rate uses the mean of the last three days, since
// single days fluctuate.
func DeviationOn(s Series, metric string, day time.Time, window, minDays int) (Deviation, bool) {
	v, ok := s.Value(metric, day)
	if !ok {
		return Deviation{}, false
	}
	if metric == RestingHR {
		sum, n := 0.0, 0
		for i := range 3 {
			if x, ok := s.Value(metric, day.AddDate(0, 0, -i)); ok {
				sum, n = sum+x, n+1
			}
		}
		v = sum / float64(n)
	}
	norm, ok := NormalFor(s, metric, day, window, minDays)
	if !ok {
		return Deviation{}, false
	}
	return Deviate(metric, v, norm), true
}
